        } => {
            assert_eq!(*branch, 0, "first TogetherBranch branch index");
            assert_eq!(entry.get(), 2, "first TogetherBranch entry");
            assert_eq!(join.get(), 5, "first TogetherBranch join");
        }
        other => {
            return Err(format!(
                "expected first TogetherBranch at node 1, got {other:?}"
            ));
